  const updateBody = {
    title: newTitle,
    description: newDescription,
    isComplete: newIsComplete,
  } satisfies ITodoListTodo.IUpdate;

  const updatedTodo: ITodoListTodo =
    await api.functional.todoList.user.todoListTodos.update(connection, {
